  "customKeys.title": "Saját billentyűk",
  "customKeys.intro": "A parancskereső bármelyik parancsát saját billentyűre teheted: eszközt, alakzatot, a középre igazítást a munkasíkon, az alakzatpanelt. A billentyűid ebben a böngészőben maradnak.",
  "customKeys.add": "Billentyű hozzáadása",
  "customKeys.find": "Parancs keresése …",
  "customKeys.noCommand": "Egyetlen parancs sem illik ide.",
  "customKeys.press": "Nyomd meg a billentyűt ehhez: „{command}” · Esc: mégse",
