  "customKeys.unavailable": "„{command}” most nem indítható – gyakran azért, mert semmi sincs kijelölve.",
  "shortcuts.group.help": "Súgó",
  "shortcuts.commandSearch": "A parancskereső megnyitása",
  "installHint.chromium": "Telepítsd a címsor jobb oldalán lévő ikonnal, vagy a böngésző menüjéből az „Alkalmazás telepítése” pontnál.",
  "installHint.safariMac": "Safariban: Fájl menü → „Hozzáadás a Dockhoz”.",
  "installHint.ios": "Safariban: Megosztás ikon → „Főképernyőhöz adás”.",
  "installHint.firefox": "A Firefox nem tud alkalmazást telepíteni – a layerling itt a lapon így is elindul offline.",
  "welcome.moreOfflineTitle": "Offline is működik",
  "welcome.moreOfflineBody": "az első látogatás után a layerling internet nélkül is elindul – telepítsd úgy, mint egy normál programot, a terveid a gépeden maradnak.",
  "welcome.moreAiTitle": "Építés MI-vel",
  "welcome.moreAiBody": "az MCP-felületen keresztül egy MI-asszisztens alakzatokat hozhat létre és szerkeszthet egy általa megnyitott szerkesztőben. Ehhez egy saját magad által futtatott példány kell (npm run dev, vagy a Docker-kép); a layerling.com oldalon az MI-kapcsolat ki van kapcsolva.",
  "welcome.morePointsTitle": "Viszonyítási pontok",
  "welcome.moreSearchTitle": "Parancskereső",
  "welcome.moreSimplifyTitle": "Hálók egyszerűsítése",
  "welcome.moreSimplifyBody": "Egy nagyon sok háromszögből álló importált háló a töredékére csökkenthető, előtte-utána nézettel és csúszkával – így a vágás, a csoportosítás és a húzás gördülékeny marad.",
  "welcome.moreHistoryTitle": "Előzmények",
  "welcome.moreLookTitle": "Olyan, amilyennek szereted",
  "welcome.moreLookBody": "A háttér és a munkasík, az X, Y és Z tengelynyilai, az élvonalak minden testen, a vázlat színei, valamint a kontraszt, az árnyékok és a fény iránya a beállításokban állítható – például hogy a sötét testek ne olvadjanak egybe. Lassabb gépeken a gyors mód egyszerre kikapcsol minden erőforrás-igényes dolgot.",
  "welcome.moreTabletTitle": "Táblagépen",
  "welcome.moreTabletBody": "egy ujj úgy dolgozik a terven, mint a bal egérgomb, két ujj nagyít és mozgatja a nézetet; egy Bluetooth-billentyűzettel a gyorsbillentyűk is működnek.",
  "welcome.moreHistoryBody": "a projekt bármelyik korábbi állapota visszanézhető egy csúszkával, változtatás nélkül – az az állapot exportálható, vagy új projekt indítható belőle.",
  "welcome.moreDrawingTitle": "Rajz a műhelynek",
  "welcome.moreDrawingBody": "Exportálás → Rajz: elöl-, felül- és oldalnézet 1:1 arányban ISO-lapon, befoglaló méretekkel, takart élekkel és a kerek furatok táblázatával – PDF-ként vagy SVG-ként, nyomtatáshoz vagy az esztergához és a maróhoz.",
  "welcome.moreSearchBody": "Nyomd meg a Ctrl+K-t, és írd be egy eszköz, alakzat vagy parancs nevét, hogy egyenesen odaugorj – angolul vagy németül, mindegyik mellett a billentyűparanccsal. A terved testeit is megtalálja név szerint. Bármelyiket saját billentyűre is teheted.",
  "welcome.moreHelpTitle": "Interaktív súgó",
  "welcome.moreHelpBody": "nyomd meg a Shift+F1 billentyűt vagy a kérdőjelet, majd kattints egy gombra, mezőre vagy ablakra: egy kis ablak megmutatja az útmutató róla szóló részét.",
  "welcome.morePointsBody": "kattints jobb gombbal egy testre, és jelöld meg a középpontját, sarkait vagy élfelezőit pontokkal, amelyek nem nyomtatódnak ki, és amelyekhez az alakzatok illeszkednek – így egy lyukat pontosan egy másik rész közepére tehetsz.",
  "welcome.videosTitle": "Videók a layerlingről",
  "welcome.videosHint": "Mások készítették, nem ez a projekt. A linkek új lapon nyitják meg a YouTube-ot; kattintásig onnan semmi sem töltődik be.",
  "welcome.help": "A szerkesztőben a Súgó csoportban van egy rövid útmutató és az összes billentyűparancs listája. A láblécben a „Hibajelentés” elmenti a tervedet mindazzal, ami egy fórumos vagy GitHubos bejelentéshez kell.",
  "welcome.guideLink": "A teljes, képes útmutató elolvasása",
  "welcome.guideUrl": "/guide/index.html",
