  "hinge.leafPlate": "Lap",
  "hinge.leafFingers": "Ujjak",
  "hinge.leafFingersHint": "Minden zsanérszem saját ujjat visz; a két oldal ujjai felváltva követik egymást, mint két fésű. Így a zsanér teljesen körbehajlik, és a zsanérszemmel egyező vastagságú kúpokkal és ujjakkal laposan zár. Egy oldal ujjait nem köti össze szárny: illeszd őket a saját modelledhez, például egy dobozhoz és a fedeléhez.",
  "hinge.leafRaised": "Megemelt szárny",
  "hinge.leafRaisedHint": "A második szárny magasabban fekszik, így zárva a hézaggal együtt laposan fekszik az elsőn, és a zsanér jóval a lapos helyzeten túl is hajlik. A megemelt szárny alá támasszal nyomtasd.",
