  "shell.edges.sharp": "Éles",
  "shell.edgesHint": "Ott érvényes, ahol a belső falak eltávolodnak egymástól, egy lépcsőnél vagy nyílásnál. Egy egyszerű doboz sarkai belül élesek maradnak – a lekerekített belsőhöz előbb a külső éleit kerekítsd le.",
  "shell.stack": "Egymásra rakható",
  "shell.stackHeight": "A talp magassága",
  "shell.stackHint": "Az alja talppá válik, a falvastagsággal keskenyebben, amely beleillik az alatta lévő doboz nyílásába, ahogy a Gridfinity-tárolók egymásra rakhatók. Fölötte a doboz 45°-ban kiszélesedik, így támasz nélkül nyomtatható; a fenék a talp fölött van. A teteje nem változik, ezért minden fedél ráillik.",
  "shell.stackWallThin": "A fal túl vékony a rakásoláshoz: legalább {min} mm.",
