  "shell.errorStackNotStraight": "A falak nem függőlegesek: az alja nem olyan széles, mint a teteje, így egy doboz nem illene a következőbe. Kapcsold ki a rakásolást.",
  "shell.errorStackFailed": "A talpat nem sikerült megépíteni ezen a testen. Kapcsold ki a rakásolást, vagy válassz másik falat.",
  "shell.shelf": "Polctartó perem",
