  "shell.shelfHeight": "A perem magassága",
  "shell.shelfHint": "A fal belső oldalán körbefutó perem, amelyen egy lap nyugszik. A magasságot a fenék belső oldalától a perem felső síkjáig mérjük.",
  "shell.errorShelfNeedsTop": "A polctartó perem csak olyan testen működik, amely csak felül nyitottan van kivájva.",
  "shell.errorShelfHeight": "A polctartó perem ebben a magasságban nem fér el. Válassz másik magasságot, vagy kapcsold ki a polctartó peremet.",
  "shell.errorShelfNotStraight": "A falak nem egyenesek, a perem nem ülne egyenletesen. Kapcsold ki a polctartó peremet.",
  "shell.errorShelfFailed": "A polctartó peremet nem sikerült megépíteni ezen a testen. Válassz keskenyebb peremet, vagy kapcsold ki.",
