  "shell.errorCannotHollow": "Ez a test nem üregelhető ki, még nagyon vékony fallal sem. A körvonala valószínűleg nem elég tiszta a CAD-kernelnek; ezt okozhatja egy külső élig érő kivágás, például egy importált alakzat aljáig levágott ajtónyílás.",
  "shell.errorNoFlatTop": "Ennek a testnek nincs sík felső lapja, amely nyitva maradhatna. A gömbök és a szabad formák így nem üregelhetők ki.",
  "shell.errorNoFlatBottom": "Ennek a testnek nincs sík alsó lapja, amely nyitva maradhatna.",
  "edge.errorOldRevolve": "Ezt a forgatott testet egy régebbi layerling hálóként építette fel. Nyisd meg a Vázlat szerkesztése pontot, és fejezd be újra, hogy pontos test legyen; utána kiüregelhető, lekerekíthető és letörhető.",
  "shell.errorNoFlatSide": "Ennek a testnek a választott oldalon nincs sík lapja, amely nyitva maradhatna.",
  "shell.errorProjectChanged": "Az objektum vagy a projekt megváltozott a kiüregelés közben; próbáld újra.",
