  "lid.help": "A fedél követi a test körvonalát és a tetején lévő nyílást. Előbb üregeld ki a testet nyitott tetővel. A fedél mellette jelenik meg, megfordítva, lapjával lefelé, nyomtatásra készen.",
  "lid.type": "Fajta",
  "lid.type.plug": "Benyomható",
  "lid.type.cap": "Ráhúzható",
