  "lid.type.bayonet": "Bajonettzáras",
  "lid.type.slide": "Becsúsztatható",
  "lid.type.plugHint": "A testtel egyező méretű lap, alatta egy peremmel, amely a nyílásba illeszkedik.",
  "lid.type.capHint": "Egy falnyival szélesebb lap a testnél, alatta egy peremmel, amely kívülről ráhúzódik.",
  "lid.type.bothHint": "Egy falnyival szélesebb lap a testnél, egy a nyílásba illeszkedő és egy kívül ráhúzódó peremmel: a test fala a kettő közötti horonyban ül, mint egy ételtároló dobozon.",
  "lid.type.flatHint": "Csak egy testtel egyező méretű lap, ráfektetni vagy ráragasztani.",
  "lid.type.screwHint": "Kupak, amelynek peremében belső menet van, és a test tetején lévő ugyanilyen külső menetre csavarható, mint egy befőttesüvegen. Kerek testhez: henger, cső, kerek edény.",
  "lid.type.screwInHint": "A peremen fekvő lap, alatta menetes dugóval, amely a test nyílásában lévő ugyanilyen belső menetbe csavarható. Kerek nyílású kerek testhez: henger, cső, kerek edény.",
  "lid.type.bayonetHint": "Kupak, amelyet a test tetejének külső oldalán lévő bütykökre nyomsz, majd elfordítva reteszelsz, mint egy bajonettzárat. Kerek testhez: henger, cső, kerek edény.",
  "lid.type.slideHint": "Lap, amely az egyik falon át csúszik be, az élei a másik három fal hornyaiban futnak, mint egy fa tolltartón. Egyenes falú dobozhoz.",
