  "lid.threadPitch": "Menetemelkedés",
  "lid.threadTurns": "Fordulatok",
  "lid.threadOffset": "Menet eltolása",
  "lid.threadOffsetHint": "Milyen mélyen kezdődik a menet a perem alatt. 0-nál a peremnél kezdődik; nagyobb értéknél felette sima falszakasz marad, és a kupak pereme (vagy a dugó) ennyivel lejjebb ér.",
  "lid.screwHint": "A test tetejének külsejére {depth} mm mély menet kerül, a kupak peremének belsejébe ugyanez, amely {height} mm-re ér le. A fogoldalak 45°-osak, így mindkettő támasz nélkül nyomtatható.",
  "lid.screwInHint": "A test nyílásának belsejébe {depth} mm mély menet kerül, a fedélre ugyanez a lapja alatti dugón, amely {height} mm-re ér le. Ahol van hely, a dugó {wall} mm falú gyűrű. A fogoldalak 45°-osak, így mindkettő támasz nélkül nyomtatható.",
  "lid.screwThreadName": "{name} menet",
  "lid.threadStandard": "Menet",
  "lid.threadStandard.own": "Egyéni",
  "lid.threadStandardHint.pco1881": "A legtöbb víz- és üdítős palack: a 28 mm-es nyak a rövid menettel.",
  "lid.threadStandardHint.pco1810": "Régebbi italos palackok: a 28 mm-es nyak a magasabb menettel.",
  "lid.threadStandardHint.gl45": "Laboratóriumi üvegek GL 45 menettel (DIN 168).",
  "lid.threadStandardHint.mason70": "Normál szájú befőttesüvegek (Mason). A menetükről nincs közzétett rajz, a méretek mértek: előbb próbáld ki a kupakot a saját üvegeden.",
  "lid.threadStandardHint.mason86": "Széles szájú befőttesüvegek (Mason). A menetükről nincs közzétett rajz, a méretek mértek: előbb próbáld ki a kupakot a saját üvegeden.",
  "lid.screwStandardHint": "A kupak ehhez a nyakhoz illik: {standard}. A menete {major} mm átmérőjű, fordulatonként {pitch} mm; {depth} mm-re ér le. Az a test, amelynek a teteje olyan széles, mint a nyak a menet alatt ({from}–{to} mm), megkapja a nyak menetét; minden más változatlan marad, és csak a kupak készül el. A fogoldalak a szabvány szerintiek, meredekebbek 45°-nál.",
  "lid.neckMeasuring": "A test tetejének mérése…",
  "lid.neckFits": "A tested teteje: {measured} mm átmérőjű. Ez a nyak a menet alatt {from}–{to} mm: {standard}, így a tested is megkapja a menetet.",
  "lid.neckSize": "A tested teteje: {measured} mm átmérőjű. Ehhez a nyakhoz {from}–{to} mm kell a menet alatt: {standard}, ezért csak a kupak készül el.",
  "lid.neckNotRound": "A tested teteje nem kerek, ezért csak a kupak készül el.",
  "lid.neckFit": "A test illesztése a nyakhoz",
  "lid.neckFitHint": "A testet {diameter} mm átmérőjűre állítja, a magasságát megtartja, így a Fedél készítése megadja neki a menetet.",
  "lid.neckFitting": "A test illesztése…",
  "lid.neckFitByHand": "Állítsd a tetejét {diameter} mm átmérőjűre, és ő is megkapja a menetet.",
  "lid.bayonetLugs": "Bütykök",
  "lid.bayonetTurn": "Fordulás (0 = automatikus)",
  "lid.bayonetTurnHint": "Legfeljebb 90°, negyed fordulat, amennyit két bütyök enged. Több bütyök vagy kis test kevesebb helyet hagy a hornyoknak és a köztük lévő ütközőknek: a nem elférő fordulat ilyenkor arra korlátozódik, ami elfér, és az állapotsor jelzi.",
  "lid.bayonetAxialGap": "Hézag magasságban",
  "lid.bayonetDetent": "Rögzítőbütyök magassága",
  "lid.bayonetDetentHint": "Kis borda minden reteszelt bütyök mögött, amelyen kattanva átjut, így a kupak nem fordul vissza magától; 0 = nincs, kisebb, ha a kupak túl nehezen fordul.",
  "lid.bayonetHint": "Bütykök: {count}, a test tetejének külsején, az átmérőjéből méretezve, és mindegyikhez egy L alakú horony a kupak peremének belsejében. Nyomd rájuk a kupakot, és fordítsd el {turn}°-kal az óramutató járásával megegyezően, amíg kattan. A bütykök és a hornyok alul 45°-ban lejtenek, így mindkettő támasz nélkül nyomtatható.",
  "lid.bayonetLugsName": "{name} bütykök",
  "lid.slideSide": "Becsúszik innen",
  "lid.slideHint": "A fedél élei három fal hornyaiban futnak; a negyedik a fedél aljáig le van vágva, így a fedél felette becsúszik, és a vége kitölti a vágást. A hornyok teteje 45°-ban lejt, így a doboz állva, a fedél a tetején nyomtatható, mindkettő támasz nélkül.",
  "lid.slideFrame": "Keret a fedél felett",
  "lid.slideFrameHint": "Mennyivel ül a fedél a perem alatt, a falak keretként állnak körülötte. 0: a fedél egy síkban van a peremmel.",
  "lid.slideHintFrame": "A fedél a perem alatt ül, az élei három fal hornyaiban futnak; a negyedik falon lévő résen át csúszik be, amely felette megtartja a teljes magasságát, és a vége kitölti a rést. A doboz állva nyomtatható, a rés teteje áthidalva; a fedél a tetején, támasz nélkül.",
  "lid.slideBumpHint": "Egy kis bütyök a fedél vége alatt kattanva átjut annak a falnak a belső élén, amelyen át becsúszik, így a fedél nem csúszik ki magától. A bütyök magassága azt adja meg, mennyire áll ki a fedél alól: kis doboznál kevesebb, határozottabb kattanáshoz több.",
  "lid.slideGroovesName": "{name} fedélhornyok",
  "lid.tether": "Rögzítőpánt",
  "lid.tetherHint": "Nyitva is a testnél tartja a kupakot, mint egy italos palacknál: két nyitott gyűrű egy szalaggal összekötve, laposan nyomtatva a kupak mellett, legjobb PETG-ből vagy TPU-ból (PLA-ból csak néhány hajlítást bír). A nagyobb gyűrű alulról pattan a kupakra, a tetején körbefutó gallér alá, a kisebb a testre a kupak alatt, ahol egy perem tartja. Mindkettő szabadon fordul, így a kupak továbbra is le- és felcsavarható.",
  "lid.tetherName": "{name} rögzítőpánt",
  "lid.tetherBeadName": "{name} pánttartó perem",
  "lid.flipTop": "Felnyitható kupak",
  "lid.flipTopOpening": "Nyílás",
  "lid.flipTopHint": "Kerek nyílás a kupak lapján, benne egy fedőlappal, egy síkban a tetővel. A fedőlap hátulján egy vékony csík a zsanérja, így a kupak a helyén marad, és a fedőlap sosem esik le. A rajta keresztben futó horonyba akasztott körömmel emeld fel, és nyomd le, amíg kattan. PETG-ből vagy PP-ből nyomtasd: PLA-ból a csík néhány hajlítás után eltörik.",
  "lid.topEdge": "Felső él",
  "lid.topEdge.square": "Szögletes",
  "lid.topEdge.round": "Lekerekített",
  "lid.topEdge.chamfer": "Letört",
  "lid.topEdgeSize": "Él mérete",
  "lid.topEdgeThin": "A lap ennél vékonyabb: az él {size} mm lesz.",
  "lid.topEdgeHint": "Lekerekíti vagy letöri a kupak külső felső peremét. A kupak megfordítva nyomtatódik, így ez az él az asztalon fekszik: egy élletörés tisztán nyomtatható, és egy 1-2 mm-es lekerekítés is.",
  "lid.working": "A fedél készül…",
  "lid.apply": "Fedél készítése",
