  "lid.error.rimNotLevel": "A perem lejt. A fedélhez vízszintes perem kell. A lejtést követő fedélhez üregeld ki a testet zártan, és használd a Kettévágást egy döntött síkkal ott, ahol a fedélnek le kell jönnie.",
  "lid.error.tooSmall": "A nyílás túl kicsi egy ilyen hézagú peremhez. Válassz kisebb hézagot vagy lapos fedelet.",
