  "lid.hingeHint": "A zsanérszemek felváltva a testen és a fedélen vannak, mindegyiken átmenő furattal a csapnak. 1,75 mm-be egy darab filament is jó, nyomtatott csap kb. 3 mm-től tart. Zsanérszemek: {diameter} mm.",
