  "historyStep.offsetOne": "{name} eltolva",
  "historyStep.offsetMany": "{count} objektum eltolva",
  "guide.edges.offset": "Az eltolás a test minden lapját ugyanannyival mozgatja kifelé vagy befelé. Nagyíts egy másolatot, és tartsd meg lyukként, így megkapod az illesztés játékát; vagy kicsinyíts egy testet egy lyukba illő csaphoz. A csak háromszöghálóból álló testeket gyakran nem lehet eltolni.",
  "deleteFace.title": "Lap törlése",
  "deleteFace.subtitle": "A környező lapok bezárják a rést",
  "deleteFace.help": "Kattints a törlendő lapokra; egy újabb kattintás kiveszi a lapot a kijelölésből. A környező lapok addig nőnek, amíg a rés bezárul: egy lekerekítés, egy furat vagy egy kiemelkedés eltűnik, a test pedig pontos marad. Az egy síkban lévő lapok közötti hajszálvékony lapok a kiválasztott lapokkal együtt törlődnek.",
  "deleteFace.preparing": "Lapok beolvasása…",
  "deleteFace.countNone": "Még nincs kiválasztott lap",
  "deleteFace.countOne": "1 lap kiválasztva",
  "deleteFace.countMany": "{count} lap kiválasztva",
  "deleteFace.thinOne": "Velük együtt törlődik: 1 hajszálvékony lap",
  "deleteFace.thinMany": "Velük együtt törlődik: {count} hajszálvékony lap",
  "deleteFace.apply": "Lapok törlése",
  "deleteFace.working": "Lapok törlése…",
  "deleteFace.cancel": "Lap törlésének megszakítása",
  "deleteFace.errorUnchanged": "Ezek a lapok nem törölhetők: a környező lapok nem zárják be a rést. Válaszd ki annak minden lapját, aminek el kell tűnnie - például egy lekerekítés összes lapját vagy egy furat teljes falát -, és a test saját lapjai közül egyet se.",
  "deleteFace.errorMesh": "Ennek a testnek nincsenek törölhető pontos lapjai: a layerling hálóként tárolja, mint egy importált STL, OBJ vagy 3MF fájlt, egy kettévágott, hengerre tekert vagy egyszerűsített testet, vagy egy nagyon részletes formát, például egy hosszú szöveget. A STEP-ként importált alkatrésznek vannak pontos lapjai.",
  "deleteFace.errorResized": "Ennek a testnek a méretét bekapcsolt „Élméret megtartása átméretezéskor” mellett változtatták meg, így a pontos lapjai már nem illenek hozzá. Vond vissza az átméretezést, töröld a lapokat, majd méretezd át újra.",
  "deleteFace.errorProjectChanged": "Az objektum vagy a projekt megváltozott a lapok törlése közben; próbáld újra.",
  "deleteFace.errorFailed": "A lapokat nem sikerült törölni. Válassz más lapokat.",
  "deleteFace.errorNoFaces": "Ennek a testnek a lapjait nem sikerült beolvasni. Zárd be az eszközt, és nyisd meg újra.",
  "deleteFace.errorTooSlow": "Ezeknek a lapoknak a törlése túl sokáig tartott, és 45 másodperc után leállítottuk; semmi sem változott. A CAD-mag ezen az alkatrészen nem boldogul ezekkel a lapokkal: válassz más vagy kevesebb lapot.",
  "status.facesDeletedOne": "1 lap törölve",
