  "editor.bugReport": "Hibajelentés",
  "editor.bugReportHint": "Hibajelentés mentése ZIP-ként: a terv a verziójával, a böngészővel és az utolsó üzenetekkel, hogy csatold a fórumon vagy a GitHubon",
  "bugReport.fileSuffix": "hibajelentes",
