  "status.faceToolReady": "Lap kiválasztva. Állítsd be a távolságot, a sarokrádiuszt és a mélységet.",
  "status.faceToolCreated": "Lap kihúzva {depth} mm-rel",
  "status.faceToolPocketCreated": "{depth} mm mély zseb kivágva a lapba",
  "status.faceToolFailed": "A lapeszköz nem tudta felépíteni ezt a testet: {message}",
  "status.honeycombConverted": "Méhsejt lyukmintává alakítva, lyukak: {count}",
  "welcome.moreHolePatternTitle": "Lyukminta",
  "welcome.moreHolePatternBody": "Kattints egy test sík lapjára, és szórj rá lyukakat: kereket, négyzetet, téglalapot, hatszöget vagy hosszlyukat, rácsban vagy eltolva, osztással, a széltől mért szegéllyel és mélységgel (az egész testen át vagy megadott mélységig). Létrehozás előtt előnézet mutatja a lyukakat; utána közönséges lyukak maradnak, a testtel csoportosítva – szellőzőkhöz, hangszórórácsokhoz, kosarakhoz és dobozokhoz. Vagy tegyél csavarlyukak koszorúját az él mentén, minden sarokra egyet, igény szerint hengeres vagy kúpos süllyesztéssel. Ugyanígy ismételhető egy saját forma is, szegecsek vagy recés lemez. Henger vagy cső kerek falán a lyukak teljesen körbefutnak, mindegyik a tengely felé mutat.",
  "welcome.moreSupportRibTitle": "Támasztóborda",
  "welcome.moreSupportRibBody": "Nyomtass élére döntött alkatrészt a szeletelő támaszai nélkül: kattints az alsó lapjára, és alatta kis réssel vékony borda áll ovális talpon, pontosan egy réteg magas apró hidakkal, amelyek tartják az alkatrészt, és utána letörhetők.",
  "welcome.moreStencilBridgesTitle": "Sablonhidak",
  "welcome.moreStencilBridgesBody": "Nyomtass sablont átvágott szöveggel: az olyan betűk közepe, mint az o, a és b, kis hidakat kap a lemezhez, olyan szélesen és magasan, ahogy szeretnéd, így semmi sem esik ki.",
  "welcome.moreFaceTitle": "Lap kitolása",
  "welcome.moreFaceBody": "egy test sík lapját kitolhatod vagy zsebet vághatsz bele, a széltől való behúzással, lekerekített sarkokkal és mélységgel, előnézettel - importált STL-eken is.",
  "guide.select.holePattern": "Lyukminta (a szalag gombja az Ismétlés mellett, jobb kattintás egy testen, vagy Ctrl+K): kattints egy sík lapra vagy kerek falra, majd állítsd be a lyuk alakját, méretét, az osztást, az elrendezést, a szegélyt és a mélységet. A lyukak előnézetként látszanak; a „Létrehozás” lyukakként adja hozzá őket, a testtel csoportosítva. A csoportbontás újra szétválasztja őket.",
  "guide.select.faceTool": "Lap (a szalag gombja a Lyukminta mellett, jobb kattintás egy testen, vagy Ctrl+K): kattints egy sík lapra, válaszd a Ki vagy a Be irányt, majd állítsd be a széltől mért távolságot, a sarokrádiuszt és a mélységet. Amit hozzáad, az egy vázlattest, a testtel csoportosítva.",
  "guide.select.supportRib": "Támasztóborda (a szalag gombja, jobb kattintás egy testen, vagy Ctrl+K): kattints egy élére döntve nyomtatott alkatrész alsó lapjára. Alatta kis réssel vékony borda áll ovális talpon, amelyet egy réteg magas apró hidak tartanak az alkatrészhez; állítsd be a szeletelőd fúvókáját és rétegeit.",
  "scalePercent.errorTooSmall": "„{name}” kisebb lenne 0,01 mm-nél.",
  "scalePercent.errorTooLarge": "„{name}” nagyobb lenne, mint amit az alakzata megenged. Állíts be neki nagyobb „Egyéni mérethatárt” a beállításokban az Alakzatok alapértékei alatt, vagy válassz kisebb százalékot.",
