  "status.threadTooDense": "Egy menet {triangles} háromszögből épül fel – ez túl sok az élművelethez, amely {limit} háromszögnél megáll. Ezért a menetet az élművelet után add hozzá: előbb törd le vagy kerekítsd le a test éleit, aztán jöhet a menet. A tulajdonságok közötti fejletörés e kerülő nélkül is letöri a csavarfej peremét.",
