  "vaseCheck.lampStanding": "Álló: rögzítsd a lámpafoglalatot az alj furatában (Ø {mm} mm) az ernyőgyűrűvel; a kábel az üreges talpon fut át. A talp legyen elég magas, hogy a foglalat teste elférjen alatta – mérd le.",
  "vaseCheck.lampStandingNotch": "Álló: rögzítsd a lámpafoglalatot az alj furatában (Ø {mm} mm) az ernyőgyűrűvel; a kábel az üreges talpon és a résen fut át. A talp legyen elég magas, hogy a foglalat teste elférjen alatta – mérd le.",
  "vaseCheck.puckTooBig": "A LED-korong (Ø {puck} mm) nem fér be – alul belül csak Ø {inner} mm van.",
  "vaseCheck.puckNoDrains": "Alj nélkül (LED-korong fölé) nincsenek vízelvezető lyukak.",
  "vaseCheck.ledOnly": "Csak LED-izzót használj: a PLA kb. 55 °C-tól, a PETG kb. 80 °C-tól lágyul.",
  "vaseCheck.drainsFew": "Csak ennyi vízelvezető lyuk fér el az aljban: {count}.",
  "vaseCheck.drainsNone": "Egyetlen vízelvezető lyuk sem fér el az aljban – válaszd kisebbre őket.",
  "vaseCheck.slopeLimited": "A lejtés {slope} mm-re korlátozva (alj: {floor} mm).",
  "vaseCheck.drainsNeedHollow": "Vízelvezető lyukak csak üreges vázához valók.",
  "vaseCheck.notchFoot": "A kábelréshez ({height} mm magas) legalább {foot} mm-es üreges talp kell.",
  "vaseCheck.cutoutNeedsHollow": "Áttört fal csak üreges vázához való (test: „{hollow}”).",
  "vaseCheck.cutoutLowpoly": "Az áttört fal nem fér össze a lapokkal (low poly).",
  "vaseCheck.cutoutZoneSmall": "A nyílások sávja túl kicsi – állítsd távolabbra egymástól ezeket: „{from}” és „{to}”.",
  "vaseCheck.cutoutNoRow": "A(z) „{whole}” beállítással egyetlen lyuksor sem fér el a sávban – legyen a sáv magasabb vagy a cellák kisebbek.",
  "vaseCheck.reinforceHollow": "A bordák és a dupla fal a szeletelő vázamódjához valók (test: „{solid}”) – üreges vázán nincs hatásuk.",
  "vaseCheck.reinforceLowpoly": "A bordák és a dupla fal nem férnek össze a lapokkal (low poly).",
  "vaseCheck.teapotLowpoly": "A teáskanna-fedél nem fér össze a lapokkal (low poly).",
  "vaseCheck.doubleWallClose": "A falak túl közel vannak a kötőbordákhoz – legalább {mm} mm-re legyenek egymástól (négy vonalszélesség).",
  "vaseCheck.slitsKept": "Szeletelő: spirális vázamód be, külső vonalszélesség {line} mm (ahogy itt beállítottad). A hasítékok ({slit} mm) az alapbeállításokkal megmaradnak; egy borda két vonala {slit} mm-re fekszik egymástól. Szoros összeolvadáshoz: 0,03 mm hasítékszélesség és 0,01 mm „Slice gap closing radius” a szeletelőben (PrusaSlicer, OrcaSlicer, Bambu Studio).",
  "vaseCheck.slitsGap": "Szeletelő: spirális vázamód be, külső vonalszélesség {line} mm (ahogy itt beállítottad). Fontos: a „Slice gap closing radius” értékét (PrusaSlicer, OrcaSlicer, Bambu Studio) állítsd legfeljebb {radius} mm-re – különben a szeletelő bezárja a {slit} mm-es hasítékokat, és sima falat nyomtat.",
