  "export.3mf.note": "PrusaSlicerhez, Bambu Studióhoz, OrcaSlicerhez és Curához. Minden test külön rész marad a nevével és a színével.",
  "export.obj.description": "Univerzális 3D háló",
  "export.obj.note": "Széles körben támogatott hálóformátum modellezéshez, rendereléshez és adatcseréhez. A színek a csúcspontokon tárolódnak, ezeket a Bambu Studio és az OrcaSlicer beolvassa.",
  "export.step.description": "CAD / B-Rep",
  "export.step.note": "A dobozokat, hengereket, gömböket és kúpokat pontos CAD-geometriaként őrzi meg, minden olyannal együtt, aminek az éleit lekerekítették vagy letörték, valamint a STEP-ként érkezett testekkel. A menetek, rugók és fogaskerekek is a pontos testükkel mennek. A kúposított, döntött és csavart alakzatok is pontosan mennek. A szöveg is pontosan megy, betűről betűre a betűtípus saját görbéivel. Az importált hálók pontossá alakítva mennek, síkjaik, hengereik, kúpjaik, gömbjeik és tóruszaik valódi lapként; a szabad formájú háló, például egy figura, STL-ként megy.",
  "export.svg.description": "Felülnézeti vektor",
  "export.svg.note": "Tiszta felülnézeti sziluettet exportál milliméterben, a lyukakkal és az íves kontúrokkal együtt.",
  "export.svg.noteFootprint": "Csak azokat a körvonalakat exportálja, amelyekkel a tárgyak a munkasíkon állnak, vonalakként milliméterben, lézervágáshoz és sablonokhoz.",
  "export.svg.noteEdges": "A felülről látható éleket vonalakként exportálja milliméterben, minden testet a saját színével: körvonalak, furatok, zsebek és gravírozások, minden terület zárt, lézergravírozáshoz és plotterekhez.",
