  "export.bridgeWidth": "Híd szélessége",
  "export.bridgeCount": "Hidak részenként",
  "export.svg.viewEdges": "Látható élek felülről",
  "export.dxf.description": "Lézervágó körvonal",
  "export.dxf.note": "A felülnézeti körvonalat exportálja lézervágó cégeknek: egyenesek, valódi ívek és körök a 0-s rétegen, fehér színnel, milliméterben. Az összeérő testekből egy körvonal lesz.",
  "export.dxf.noteFootprint": "Csak azokat a körvonalakat exportálja, amelyekkel a tárgyak a munkasíkon állnak, lézervágó cégeknek: egyenesek, valódi ívek és körök a 0-s rétegen, fehér színnel, milliméterben.",
  "export.lyl.description": "A layerling saját tervformátuma",
  "export.lyl.note": "Megőrzi a szerkeszthető tervet, a visszavonási/ismétlési előzményeket, a vázlatokat, a csoportokat, a CAD-adatokat és az importált forrásokat. A régebbi .skf fájlok is megnyílnak, és .lyl-ként mentődnek. Chrome-ban és Edge-ben te választod ki a mappát és a nevet, a Ctrl+S pedig utána újra abba a fájlba ment; a fájlból megnyitott terv vissza is abba ment.",
  "import.openProject": "layerling terv megnyitása",
