  "hinge.styleLiftOffHint": "Két csukló: az alsó a csapot viszi végig, a felső egy hüvely, amely leemelhető róla. Az Alkatrészek szétválasztása a két darabot adja; állva nyomtatáshoz a csapos darabot a csuklójára, a másikat a hüvelyére állítsd.",
  "hinge.styleSnap": "Bepattintós",
