  "sketch.edit": "Szerkesztés",
  "welcome.moreHullTitle": "Burok",
  "welcome.moreHullBody": "egyetlen domború testbe burkolja a kijelölt alakzatokat, mintha zsugorfóliával vonnád be őket: egy hengeren ülő félgömbből lépcső nélküli kupola lesz, négy sarokoszlopból lekerekített sarkú doboz. A kijelölésben lévő lyukak utána kivágódnak a burokból, és a Csoport szerkesztése újra megnyitja.",
  "welcome.moreCookieCutterTitle": "Kekszkiszúró",
  "welcome.moreCookieCutterBody": "vázlatból, SVG-ből vagy bármilyen alakzatból kekszkiszúrót készít: vékony falat a körvonal mentén és lapos peremet a talpánál. A körvonal tükrözve van, így a szöveg helyes irányban jön ki a tésztából, a fal pedig vágóélben végződik. Egy e vagy a belseje saját falat kap, hidakkal tartva – alacsonyabbra véve csak benyomja a szöveget a tésztába –, a falat, az élt, a magasságot és a peremet pedig utólag a Tulajdonságok alatt módosíthatod.",
  "welcome.moreFlexiTitle": "Flexi csuklók",
  "welcome.moreFlexiBody": "egy lapos testet – egy magad rajzolta halat, kígyót vagy sárkányt – láncszemekre vág, és minden vágásnál a helyén nyomtatott csuklót tesz bele, így a figura nyomtatás után mozog, támasz és összeszerelés nélkül.",
  "welcome.moreLidTitle": "Fedél",
  "welcome.moreLidBody": "fedelet készít egy felül nyitott dobozhoz, edényhez vagy tálcához: a nyílásba nyomva, kívülről ráhúzva, a falat két oldalról fogva vagy laposan ráfektetve, az általad választott illesztéssel, nyomtatásra készen mellette.",
  "welcome.moreSlopeTitle": "Lejtés és szűkülés hosszában",
  "welcome.moreSlopeBody": "egy doboz, henger, ék vagy íves tető tetejét az egyik vége felé lejteni engedi, vagy az oldalait az egyik vége felé szűkíti, egyenesen vagy ívesen: hosszában lejtő tető, rámpa, hajóorr.",
  "welcome.moreAttachmentsTitle": "Fájlok a tervvel",
  "welcome.moreAttachmentsBody": "jegyzetek és listák .md vagy .txt formában, a nyomtatott alkatrész fényképe (.png, .jpg, .webp) vagy egy adatlap PDF-ként a terven belül maradnak, és a .lyl fájllal együtt utaznak. A szem ikon egy ablakban mutatja a szöveget vagy a képet; a PDF letöltődik.",
  "welcome.moreEarlierVersionsTitle": "Korábbi változatok",
  "welcome.moreEarlierVersionsBody": "mielőtt a Mentés felülír egy fájlt, a layerling megőrzi az előző állapotát, munka közben pedig néhány percenként elteszi a terv állapotát; mindegyik új tervként nyitható meg újra, Chrome-ban és Edge-ben pedig egy saját mappába is kerülhetnek.",
  "welcome.moreLanguagesTitle": "A te nyelved",
  "welcome.moreLanguagesBody": "a program és az útmutatója angolul, németül és még 18 nyelven beszél; a nyelvválasztó jobb oldalt legfelül van, és a kezdőlap beállításaiban.",
  "welcome.moreControlsTitle": "Egér és 3D egér",
  "welcome.moreControlsBody": "ha szeretnéd, az egérgombok úgy működnek, mint a Bambu Studióban és az OrcaSlicerben – üres helyen bal gombos húzás forgatja a nézetet, a jobb gomb eltolja –, és Chrome-ban és Edge-ben SpaceMouse-szal is irányíthatod a nézetet.",
  "sketch.revolvePreviewReset": "Nézet visszaállítása (dupla kattintás)",
  "sketch.traceLoading": "A kép beolvasása…",
  "sketch.traceUnreadable": "A képet nem sikerült beolvasni.",
