  "sketch.traceApply": "Alkalmazás",
  "mate.stepPoint.source": "1. Kattints ennek a testnek arra a pontjára, amelynek mozdulnia kell: egy csúcsra, egy él egy pontjára, egy kerek él közepére vagy egy referenciapontra.",
  "mate.stepPoint.target": "2. Kattints arra a pontra egy másik testen vagy referenciapontra, ahová kerülnie kell.",
  "mate.stepPoint.ready": "Mindkét pont kiválasztva. Válaszd ki a tengelyeket, amelyek mentén mozdul, majd alkalmazd.",
  "mate.stepPoint2.source": "2. pár (nem kötelező): kattints ennek a testnek egy második pontjára. Az első, kékkel jelölt pont körül fordul.",
  "mate.stepPoint2.target": "Kattints arra a pontra egy másik testen vagy referenciapontra, amely felé fordulnia kell.",
  "mate.stepPoint2.ready": "A második pár kiválasztva. A Fordítás az első pont körül fordítja a testet.",
  "mate.stepPoint3.source": "3. pár (nem kötelező): kattints ennek a testnek egy harmadik pontjára. A két kék ponton átmenő vonal körül fordul.",
  "mate.stepPoint3.target": "Kattints arra a pontra, amely meghatározza, mennyit forduljon a vonal körül.",
  "mate.stepPoint3.ready": "A harmadik pár kiválasztva. A Fordítás a vonal körül fordítja a testet.",
  "mate.turnHint2": "Az első pont a helyén marad. A test csak fordul, így a második pontja a másik felé mutató vonalra kerül, a saját távolságában. A Kész a testet a mostani állapotában hagyja.",
  "mate.turnHint3": "Az első két pont a helyén marad. A test csak a rajtuk átmenő vonal körül fordul, amíg a harmadik pontja a másik felé néz. A Kész a testet a mostani állapotában hagyja.",
  "mate.done": "Kész",
  "mate.turn": "Fordítás",
  "mate.mode.point": "Pontot pontra",
  "mate.axes": "Mozgás ezek mentén",
  "mate.axesHint": "Ha csak X és Y van bekapcsolva, a pont pontosan a másik fölé vagy alá kerül; ha csak Z, ugyanarra a magasságra.",
  "shell.errorRoundedEdges": "Ennek a doboznak le vannak kerekítve a felső és alsó élei, és a falnak jóval vékonyabbnak kell lennie ennél a lekerekítésnél. Válassz vékonyabb falat, vagy a kiüregelés előtt állítsd 0-ra a felső és alsó élek lekerekítését. Ha így sem sikerül, a lábléc „Hibajelentés” pontja elmenti a tervet a jelentéshez.",
  "shell.errorTooSlow": "Ennek a testnek a kiüregelése túl sokáig tartott, és leállt; semmi sem változott. A CAD-kernel nem tudja kiszámolni a falakat ezen az alakzaton. Próbálj vékonyabb falat vagy más nyitott oldalakat.",
  "guide.select.matePoint": "A Lapok igazítása „Pontot pontra” módja egyenesen, forgatás nélkül mozgatja a részt, így egy csúcs, egy él egy pontja vagy egy referenciapont egy másik rész egy pontjára kerül. Kapcsold ki az X-et, Y-t vagy Z-t, hogy ne mozduljon az adott tengely mentén: csak X és Y bekapcsolva az egyik pontot pontosan a másik fölé teszi. A mozgatás után az eszköz nyitva marad még legfeljebb két párhoz, amelyek inkább forgatják a részt: a második az első pont körül, a harmadik a kettőn átmenő vonal körül – mint a hárompontos igazítás. Minden lépés egy visszavonás.",
  "guide.measure.protractor": "A nézetsáv szögmérője szöget mér: kattints a csúcsra és mindkét szár egy-egy pontjára, vagy két sík lapra. A mérőszalaghoz hasonlóan csúcsokhoz és élekhez illeszkedik, követi a mért testeket, és nem mentődik.",
  "guide.files.earlierVersions": "Korábbi változatok: mielőtt a Ctrl+S felülír egy .lyl fájlt, a fájl előző állapota megmarad, munka közben pedig néhány percenként egy állapot; az Exportálás → LYL → Korábbi változatok mindegyiket új tervként nyitja meg újra. Ezek ezen a gépen maradnak: időnként ments minden tervet egy fájlba, és tartsd azt egy második helyen – a te terveid, a te biztonsági mentésed.",
  "holePattern.countPieces.one": "1 darab fér el a lapon.",
  "holePattern.countPieces.many": "{count} darab fér el a lapon.",
  "holePattern.allowMany": "Több lyuk engedélyezése",
  "holePattern.allowManyAsk": "A minta több mint {limit} lyukat tartalmazna. Minden lyuk egyenként vágódik ki, így sokkal több lyuknál ez percekig tarthat, az oldal lefagyhat, és ha be kell zárnod, minden el nem mentett munka elvész. Előbb mentsd a tervet. Ha beleegyezel, legfeljebb {many} lyuk engedélyezett.\n\nMégis folytatod?",
  "holePattern.form.custom": "Saját alakzat",
