  "faceTool.separate": "Önálló testként (nem csoportosítva)",
  "faceTool.separateHint": "Az új rész a test mellett áll, nem vele egy csoportban: azonnal átméretezheted, mozgathatod vagy kivágásra használhatod. A kapcsoló nélkül csoportosítva lesz.",
  "welcome.moreVaseTitle": "Vázák és cserepek",
  "welcome.moreVaseBody": "saját alakzat vázákhoz, cserepekhez és lámpaernyőkhöz: testforma, keresztmetszet, csavarás, minták, vízelvezető lyukak, alátét és fedél – tömören a szeletelő vázamódjához vagy üregesen. A teáskanna-fedél a váza saját tetejét kapja, a minta átfut az illesztésen.",
  "welcome.moreOffsetTitle": "Eltolás és kivágás",
  "welcome.moreOffsetBody": "egy pontos testet adott távolsággal növel vagy csökkent, körben vagy csak oldalirányban, a sajtolt illesztés hézagához, vagy egy részt egy lépésben kivág egy másikból, körben hézaggal.",
  "welcome.morePunchTitle": "Átlyukasztás",
  "welcome.morePunchBody": "egy test körvonalát egyenesen átvágja egy másikon, ahol csak előtte áll: egy teáskanna sziluettjét egy táblán, egy logót egy fedélen. Mozgasd vagy fordítsd el a lyukasztót, és lyukassz újra; a hézag átengedi a nyomtatott részt.",
  "welcome.moreClearanceTitle": "Hézag ellenőrzése",
  "welcome.moreClearanceBody": "olyan részek nyomtatása előtt, amelyeknek mozogniuk kell – egy helyben nyomtatott zsanér, egy flexi játék, egy fedél a dobozában – megkeresi azokat a párokat, amelyek átfednek, összeérnek vagy közelebb kerülnek a beállított hézagnál.",
  "overhang.figures": "Legmeredekebb túlnyúlás: {angle}°, itt: „{name}” · {area} cm² {limit}° felett támaszt igényel",
  "overhang.figuresBelow": "Legmeredekebb túlnyúlás: {angle}°, itt: „{name}” – {limit}° alatt, semmi sem igényel támaszt",
  "overhang.figuresNone": "Nincs túlnyúlás – semmi sem igényel támaszt",
  "simplify.keepEdges": "Élek és lyukak megtartása",
  "simplify.keepEdgesHint": "Az éles élek és a lyukak peremei pontosan a helyükön maradnak, a sík lapok pedig így is elveszítik a háromszögeik nagy részét. Kikapcsolva lekerekedhetnek az alacsonyabb szám érdekében.",
  "simplify.stoppedEdges": "Itt megáll: {count} háromszög; a megtartott élek és lyukak nem engednek kevesebbet. Kapcsold ki az „Élek és lyukak megtartása” beállítást, hogy lejjebb menj.",
  "simplify.stoppedShape": "Itt megáll: {count} háromszög; kevesebbnél bezárulna egy lyuk, vagy összeolvadna két fal.",
  "makeExact.selectOne": "Jelölj ki egy importált hálót, amelyet pontossá teszel, például egy STL-t a Printablesről. A katalógus alakzatai, a vázlatok és a STEP-importok már pontosak.",
  "makeExact.working": "Síkok, hengerek, kúpok, gömbök és tóruszok keresése, háromszögek: {count}…",
  "makeExact.failed": "A talált lapok nem zárultak tömör testté, ezért a test háló marad. Egy hézagos vagy egymást keresztező falú háló nem tehető pontossá; javítsd ki, például a szeletelődben, és próbáld újra.",
  "makeExact.freeform": "Ez a test főleg szabad formájú, mint egy figura vagy egy szobrászi alakzat: a felületének csak {percent} %-a sík, hengeres, kúpos, gömb vagy gyűrű alakú. Háló marad.",
  "makeExact.tooSlow": "A test pontossá tétele túl sokáig tartott. Exportáld újra a részt kevesebb háromszöggel, vagy egyszerűsítsd bekapcsolt „Élek és lyukak megtartása” mellett, és próbáld újra.",
