  "yourBackup.title": "A te terveid, a te biztonsági mentésed",
  "yourBackup.body": "A terveid ebben a böngészőben vannak, a számítógépeden. Mint minden adatnál, csak az van biztonságban, ami egy második helyen is megvan. Egy meghibásodó meghajtó, egy új gép, törölt böngészőadatok vagy egy programhiba, és biztonsági mentés nélkül a munka elvész. A mentés a te dolgod, ezt egyetlen program sem tudja helyetted megcsinálni. A layerling megkönnyíti: a „{button}” egyetlen kattintással minden tervet egy fájlba tesz. Tartsd pendrive-on, felhőmappában vagy NAS-on, minden nagyobb munka után.",
