  "workspace.printerPlayHint": "Nyomtasd ki egyszer az illesztési tesztet, és dugd a csapját a furatokba: a legszorosabb furat, amelyben a csap még elfordul, adja a nyomtatód holtjátékát. Írd be vagy válaszd ki fent, és az új fedelek, fecskefarkak, bepattanó kötések, anyák, a Hézag ellenőrzése és a Kettévágás csatlakozói ebből indulnak.",
