  "prop.screwHoleSlotLengthHint": "Milyen hosszan fut a furat a hosszabbik oldala mentén, hogy a rész a csavar meghúzása előtt még mozgatható legyen. A hosszlyuk irányát a furat elforgatásával állítod.",
  "prop.screwHoleRecess": "Mélyítés",
  "prop.screwHoleRecessHint": "Mennyivel ül a csavarfej a lap alatt: egyenes zseb a kúp felett, olyan széles, mint a fej. 0-nál egy síkban marad; a kétoldali kúpos süllyesztésnél mindkét végén van.",
  "prop.screwHoleChamfer": "Peremletörés",
  "prop.screwHoleChamferHint": "Ilyen mély 45°-os élletörés a zseb felső élén. A fej átmérőjén kívül nyílik, így a csavarfej továbbra is befér; 0-nál az él éles marad.",
  "prop.screwHoleLengthBelowHead": "Csavarhossz",
  "prop.screwHoleLengthBelowHeadHint": "A belső kulcsnyílású hengeres fejű csavarokat a fej alól mérik. Ide írd a hosszukat, és a fej mélysége hozzáadódik a teljes hosszhoz.",
