  "inspector.surfaceCrackSeedHint": "Ugyanaz a kezdőérték, ugyanazok a repedések – egy másik újra kidobja őket. A hossz a magasság %-ában számít, a pereműtől a közepéig a sugár %-ában.",
  "inspector.surfaceCrackGold": "Arany kitöltés külön részként",
  "inspector.surfaceCrackRecess": "Arany süllyesztve",
  "inspector.surfaceCrackGoldHint": "A repedések kitöltése arany színű külön résszé válik, egy második filamenthez; teteje ennyivel van a felület alatt. Ehhez a minta a testbe megy.",
  "inspector.surfacePatternPart": "Minta külön részként",
  "inspector.surfacePatternColor": "A minta színe",
  "inspector.surfacePatternRaisedHint": "Ami kiáll a testből, ebben a színben külön résszé válik egy második filamenthez; a test marad, ahogy volt. Mindkettő csomagban megy: együtt mozognak, és a textúra továbbra is módosítható vagy levehető.",
  "inspector.surfacePatternCutHint": "Ami a testbe be van vágva, ebben a színben külön résszé válik, amely a felületig kitölti a vágást, egy második filamenthez. Mindkettő csomagban megy: együtt mozognak, és a textúra továbbra is módosítható vagy levehető.",
