  "status.surfaceNoCracks": "Egyetlen repedés sem talált utat a testen át. Próbálj másik kezdőpontot („Bárhol” bármelyik testen működik), hosszabb repedéseket, vagy hagyd, hogy a minta több lapot érjen el.",
