  "surfaceTexture.carbonTwill31": "Kepper 3/1",
  "surfaceTexture.carbonTwill22Hint": "Minden sáv két keresztező sáv fölött és két alatt fut: a legtöbb karbonalkatrész egyenletes átlója.",
  "surfaceTexture.carbonTwill21Hint": "Kettő fölött, egy alatt: az álló sávok hosszan látszanak, a keresztezők röviden.",
