  "inspector.surfaceCarbonCross": "Keresztsáv szélessége",
  "inspector.surfaceCarbonHint": "Keresztsáv szélessége 0: olyan széles, mint az álló sávok. Szélesebb vagy keskenyebb egyenetlen szövést ad. Kerek testen a sávszélesség kissé kerekítve van, hogy a szövés záródjon.",
  "inspector.surfaceSeed": "Elrendezés",
  "inspector.surfaceSeedHint": "Másik szám újra elrendezi a cellákat vagy a szemcséket.",
  "inspector.surfaceHammeredHint": "Kerek horpadások, mint a kalapácsütések, mindegyik kicsit más méretű és mélységű. A távolság adja, milyen sűrűn vannak, a horpadásméret, mennyire érnek egymásba, és másik szám az Elrendezésnél újra szétszórja őket. A Kerek profil lágyabbá teszi őket.",
  "inspector.surfaceImage": "Kép",
  "inspector.surfaceImageLoad": "Saját kép betöltése…",
  "inspector.surfaceImageHint": "A világos a teljes mélység lesz, a sötét marad, ahogy van. Átlátszó alapon lévő sötét rajz, például fekete vonalak egy SVG-ben, a vonalai szerint számít: ezek lesznek a teljes mélységűek. A saját képed szürkeárnyalatosan a tervvel együtt tárolódik, oldalanként legfeljebb 512 pontos; a csempe olyan széles, ahogy beállítod, és olyan magas, amilyen a kép ehhez a szélességhez.",
  "inspector.surfaceTileHeight": "Csempemagasság (0 = a kép szerint)",
  "inspector.surfaceImageHeight": "Képmagasság",
  "inspector.surfaceImageOnceHint": "A kép egyszer van rányomva, mint egy címke: a „Körben” és a „Magasság” a közepét helyezi el, mint a szövegnél. Rajta kívül a felület sima marad; a Mélység és az Irány azt állítja, mennyire áll ki vagy mennyire van bevágva. A 0 képmagasság megtartja a kép arányait. Kijelölt lapok esetén mindig azokra kerül.",
  "inspector.surfaceImageTurn": "Elforgatva (°)",
  "inspector.surfaceImageInvert": "Világos és sötét felcserélése",
  "inspector.surfaceImageBlur": "Lágyítás",
  "inspector.surfaceImageTiling": "Csempézés",
  "inspector.surfaceGrainHint": "Az erezet a térben fekszik, nincs levetítve: nincs varrat és nincs nyúlás, bármilyen formán ugyanaz.",
