  "editor.tool.mold": "Öntőforma és matrica",
  "mold.subtitle": "Öntőforma vagy bélyeg és matrica a kijelölt mestermintából",
  "mold.help": "A kijelölt test a mesterminta: az alak, amelyet önteni vagy préselni szeretnél. Az új részek mellé kerülnek, úgy, ahogy nyomtatódnak; a mesterminta változatlan marad.",
