  "mold.kind.tray": "Nyitott forma",
  "mold.kind.die": "Bélyeg és matrica",
  "mold.kindHint.twoPart": "Merev, kétfeles forma, amelyet kinyomtatsz, és közvetlenül önthetsz bele: gyantát, gipszet, viaszt, szappant, csokoládét vagy betont. Központosító kúpok illesztik a feleket, egy tölcsér és légzők engedik be az anyagot és ki a levegőt.",
  "mold.kindHint.box": "Keret és alaplap, hogy szilikont önts a kinyomtatott mesterminta köré. A szilikonforma minden részletet átvesz, és az olyan alámetszéseket is elengedi, amelyekben egy merev forma beragadna.",
  "mold.kindHint.tray": "Egyrészes, felül nyitott forma lapos oldalú alakokhoz: a lapos oldal lesz a nyitott teteje, színültig öntve. Egyszerű, beömlő nélkül.",
  "mold.kindHint.die": "Bélyeg és hozzá illő matrica vékony anyag – bőr, karton, fólia vagy vékony fémlemez – formázásához, dombornyomásához vagy kivágásához. A bélyeg a mesterminta felülről látott körvonala.",
  "mold.parting": "Osztás magassága",
  "mold.partingHint": "Ahol a felek elválnak, a mesterminta magasságának %-ában. Ott oszd, ahol a mesterminta a legszélesebb, különben az öntvény beragad.",
